              preferences: {
                model: Xp({
                  default: mm.model,
                  description: `Model used when asking a question in AI Chat.`,
                  key: `ai.chat.model`,
                  options: { kind: `ai-models`, feature: `chat`, allowsLastUsedModel: !0 },
                  ai: `read-write`,
                  title: `Default Model`,
                  storage: `synced`,
                }),
                routingPreference: Xp({
                  default: mm.routingPreference,
                  description: `Model preference used when Auto is the default model in AI Chat.`,
                  key: `ai.chat.routingPreference`,
                  options: {
                    kind: `ai-routing-preferences`,
                    feature: `chat`,
                    modelSetting: `model`,
                  },
                  ai: `read-write`,
                  title: `Model Preference`,
